"""D-017 source stage: generic regional graph tile cut and immutable identities."""
from __future__ import annotations

import hashlib
import gzip
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

from shapely.geometry import box, mapping

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "tools"))
import extract_f8_region_final_edges as extractor

# Generated by the Valhalla original directed shape, not a guessed B point.
APPROACH = {"endLat": 44.0, "endLon": 10.0,
            "hasNativeApproachTangent": True,
            "approachLat": 43.999, "approachLon": 10.0}


def tile(level, number, west, south, size=.25):
    return {"level": level, "tileIndex": number,
            "bounds": {"minLng": west, "minLat": south,
                       "maxLng": west + size, "maxLat": south + size}}


class RegionIndependentBoundaryTests(unittest.TestCase):
    def test_selects_only_boundary_and_immediately_neighboring_tiles(self):
        tiles = [
            tile(2, 100, 10, 44),
            tile(2, 101, 10.25, 44),
            tile(2, 102, 10.50, 44),
            tile(2, 999999, 90, 10),
        ]
        polygon = mapping(box(10.01, 44.01, 10.24, 44.24))
        actual = extractor.select_cut_tiles(
            {"schema": "roadpilot-graph-index", "tiles": tiles},
            {"type": "Feature", "geometry": polygon})
        self.assertEqual({t["tileIndex"] for t in actual}, {100, 101})

    def test_other_geography_uses_exact_same_algorithm(self):
        actual = extractor.select_cut_tiles(
            {"schema": "roadpilot-graph-index",
             "tiles": [tile(2, 240, -70, -12), tile(2, 241, -69.75, -12),
                       tile(2, 300, 35, 51)]},
            {"type": "Feature", "geometry": mapping(box(-69.99, -11.99, -69.80, -11.80))})
        self.assertEqual({t["tileIndex"] for t in actual}, {240, 241})

    def test_native_terminal_modes_and_unresolved_edges_remain_separate(self):
        terminal = {"kind": "edge", "graphId": 123, "access": 6,
                    "nativeTerminalModes": 2, **APPROACH, "isRoad": False,
                    "deadend": False}
        unresolved = {"kind": "edge", "graphId": 124, "access": 6,
                      "nativeTerminalModes": 0, **APPROACH}
        marker = {"kind": "complete", "selectedTiles": 2,
                  "valhallaVersion": "3.6.3", "edgesEmitted": 2,
                  "directedExamined": 400, "originalCutFilterApplied": False}
        lines = "\n".join(json.dumps(v) for v in (terminal, unresolved, marker))
        finals, rest, complete = extractor.classify_native_rows(
            lines, selected_count=2, version="3.6.3")
        self.assertEqual([item["graphId"] for item in finals], [123])
        self.assertEqual([item["graphId"] for item in rest], [124])
        self.assertFalse(finals[0]["isRoad"])
        self.assertFalse(finals[0]["deadend"])
        self.assertEqual(complete["directedExamined"], 400)

    def test_duplicate_missing_or_false_native_completion_fails(self):
        row = json.dumps({'kind':'edge','graphId':1,'access':4,'nativeTerminalModes':4, **APPROACH})
        marker = '{"kind":"complete","selectedTiles":1,"valhallaVersion":"3.6.3","edgesEmitted":1}'
        for lines in (row, row + "\n" + row + "\n" + marker,
                      row + "\n" + marker.replace('"selectedTiles":1', '"selectedTiles":2'),
                      row + "\n" + marker.replace('"edgesEmitted":1', '"edgesEmitted":9')):
            with self.subTest(lines=lines):
                with self.assertRaises(ValueError):
                    extractor.classify_native_rows(lines, selected_count=1, version="3.6.3")

    def test_native_tangent_is_exact_and_never_fabricated(self):
        extractor.validate_directed_approach(APPROACH)
        with self.assertRaisesRegex(ValueError, "collapses"):
            extractor.validate_directed_approach({**APPROACH, "approachLat": 44.0})
        with self.assertRaisesRegex(ValueError, "capability"):
            extractor.validate_directed_approach({"endLat": 44.0, "endLon": 10.0})
        with self.assertRaisesRegex(ValueError, "must not invent"):
            extractor.validate_directed_approach({**APPROACH,
                "hasNativeApproachTangent": False})
        extractor.validate_directed_approach({**APPROACH,
            "hasNativeApproachTangent": False,
            "approachLat": None, "approachLon": None})
        with self.assertRaisesRegex(ValueError, "Invalid native approach"):
            extractor.validate_directed_approach({**APPROACH, "approachLat": float("nan")})

    def test_local_native_node_evidence_preserves_all_forks_without_angle_heuristics(self):
        native = {"kind": "local-continuations", "source": {"graphId": 10},
                  "options": [
                    {"viaHierarchy": False, "edge": {"graphId": 11,
                        "access": 1025, "shortcut": False, "transit": False,
                        "startLat": 45., "startLon": 10., "endLat": 45., "endLon": 10.001}},
                    {"viaHierarchy": True, "edge": {"graphId": 12,
                        "access": 1024, "shortcut": True, "transit": False,
                        "startLat": 45., "startLon": 10., "endLat": 45.001, "endLon": 10.}}]}
        extractor.validate_immediate_native_observation(native)
        self.assertEqual([x["edge"]["graphId"] for x in native["options"]], [11, 12])
        with self.assertRaisesRegex(ValueError, "Duplicate"):
            extractor.validate_immediate_native_observation({**native, "options": [
                native["options"][0], native["options"][0]]})
        with self.assertRaisesRegex(ValueError, "hierarchy"):
            extractor.validate_immediate_native_observation({**native, "options": [
                {**native["options"][0], "viaHierarchy": "unknown"}]})

    def make_region(self, root: Path, region: str):
        dist = root / region
        dist.mkdir()
        manifest = dist / "routing-manifest.json"
        archive = dist / "tiles.tar"
        archive.write_bytes(b"original Valhalla archive fixture")
        idx = dist / "routing-graph-index.json"
        idx.write_text(json.dumps({
            "schema": "roadpilot-graph-index", "regionId": region,
            "packageVersion": "v1", "tiles": [tile(2, 177, 10, 44)]
        }))
        buf = dist / "buffer.geojson"
        buf.write_text(json.dumps({
            "type": "Feature", "properties": {"borderBufferKm": 25},
            "geometry": mapping(box(10.01, 44.01, 10.24, 44.24))
        }))
        sha = lambda p: hashlib.sha256(p.read_bytes()).hexdigest()
        m = {
            "schema": "roadpilot-routing-pack",
            "regionId": region, "packageVersion": "v1",
            "valhallaVersion": "3.6.3",
            "graphFingerprint": "sha256:" + sha(archive),
            "artifact": {"fileName": "tiles.tar", "sha256": sha(archive)},
            "source": {"borderBufferKm": 25,
                       "bufferGeoJsonSha256": sha(buf)},
            "graphIndex": {"sha256": sha(idx)}
        }
        manifest.write_text(json.dumps(m))
        config = dist / "valhalla.json"
        config.write_text(json.dumps({
            "mjolnir": {"tile_extract": "/wrong/old/archive.tar",
                        "tile_dir": "/wrong/old/tiles"}
        }))
        return manifest, idx, buf, config

    def test_manifest_is_region_independent_and_checks_25km_and_sha(self):
        with tempfile.TemporaryDirectory() as temp:
            region = self.make_region(Path(temp), "arbitrary-region-xyz")
            m, selected = extractor.region_input(*region[:3])
            self.assertEqual(m["regionId"], "arbitrary-region-xyz")
            self.assertEqual(len(selected), 1)
            region[2].write_text(region[2].read_text() + " ")
            with self.assertRaisesRegex(ValueError, "changed"):
                extractor.region_input(*region[:3])

    def test_streamed_json_gzip_preserves_all_candidates_and_incomplete_status(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            manifest, index, boundary, config = self.make_region(root, "some-other-region")
            binary = root / "fake-native.py"
            binary.write_text(
                "#!/usr/bin/env python3\n"
                "import json,sys\n"
                "if '--version' in sys.argv: print('3.6.3')\n"
                "elif '--protocol' in sys.argv: print('roadpilot.f8-native-source-9')\n"
                "else:\n"
                " for item in [\n"
                "  {'kind':'edge','graphId':77,'access':1025,'nativeTerminalModes':1025,'endLat':44,'endLon':10,'hasNativeApproachTangent':True,'approachLat':43.999,'approachLon':10},\n"
                "  {'kind':'edge','graphId':79,'access':1025,'nativeTerminalModes':0,'endLat':44,'endLon':10,'hasNativeApproachTangent':True,'approachLat':43.999,'approachLon':10},\n"
                "  {'kind':'complete','selectedTiles':1,'valhallaVersion':'3.6.3','edgesEmitted':2,'directedExamined':58,'originalCutFilterApplied':False}\n"
                " ]: print(json.dumps(item))\n"
            )
            binary.chmod(0o755)
            output = root / "f8-source.json.gz"
            summary = extractor.extract_to_file(
                manifest_path=manifest, index_path=index, buffer_path=boundary,
                valhalla_config_path=config, binary=binary, output_path=output)
            with gzip.open(output, "rt", encoding="utf-8") as stream:
                data = json.load(stream)
            self.assertEqual(summary["nativeTerminalCandidateCount"], 1)
            self.assertEqual(summary["unresolvedJunctionDirectedEdgeCount"], 1)
            self.assertEqual(data["regionId"], "some-other-region")
            self.assertEqual([x["graphId"] for x in data["nativeModeTerminalCandidates"]], [77])
            self.assertEqual([x["graphId"] for x in data["unresolvedJunctionDirectedEdges"]], [79])
            self.assertEqual(data["sourcePhysicalRoadFinalIdentification"], "INCOMPLETE")
            self.assertEqual(data["productionPublication"], "BLOCKED")
            with self.assertRaisesRegex(ValueError, "already exists"):
                extractor.extract_to_file(
                    manifest_path=manifest, index_path=index, buffer_path=boundary,
                    valhalla_config_path=config, binary=binary, output_path=output)

    def make_neighbor_pair(self, root: Path, first="fictional-a", second="fictional-b"):
        a = self.make_region(root, first)
        b = self.make_region(root, second)
        for here, peer in ((a,b),(b,a)):
            manifest, idx, buf, _ = here
            neighbor = json.loads(peer[0].read_text())
            owner = json.loads(manifest.read_text())
            owner["source"]["primaryGeofabrikId"] = owner["regionId"]
            index = json.loads(idx.read_text())
            index["boundaries"] = [{"sourceId": neighbor["regionId"],
                "fingerprint": "sha256:" + "e" * 64}]
            idx.write_text(json.dumps(index))
            owner["graphIndex"]["sha256"] = hashlib.sha256(idx.read_bytes()).hexdigest()
            manifest.write_text(json.dumps(owner))
        return a,b

    def test_one_region_neutral_cut_and_local_final_command_never_publishes(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            a,b = self.make_neighbor_pair(root)
            manifest, idx, buffer_file, config = a
            gid = (1 << 25) | (177 << 3) | 2
            native = root / "fake-original-local.py"
            native.write_text(
                "#!/usr/bin/env python3\n"
                "import json,sys\n"
                f"gid={gid}\n"
                "if '--version' in sys.argv: print('3.6.3')\n"
                "elif '--protocol' in sys.argv: print('roadpilot.f8-native-source-9')\n"
                "elif '--local-continuations' in sys.argv:\n"
                " assert sys.argv[4]=='--evaluate-native-costing'\n"
                " for line in open(sys.argv[3]):\n"
                "  rowid=int(line)\n"
                "  print(json.dumps({'kind':'local-continuations','source':{'graphId':rowid,'endNodeGraphId':999,'access':1025,'endLat':45,'endLon':10.01},'options':[]}))\n"
                " print(json.dumps({'kind':'complete','edgesInspected':1,'valhallaVersion':'3.6.3'}))\n"
                "else:\n"
                " assert len(sys.argv)==5\n"
                " assert 'sha-bound-shared-original-cut.geojson' in sys.argv[4]\n"
                " print(json.dumps({'kind':'edge','graphId':gid,'access':1025,'nativeTerminalModes':1025,'endNodeGraphId':999,'originalCutOrientation':'OUTWARD','endLat':45,'endLon':10.01,'hasNativeApproachTangent':True,'approachLat':45,'approachLon':10.009}))\n"
                " print(json.dumps({'kind':'complete','selectedTiles':1,'valhallaVersion':'3.6.3','edgesEmitted':1,'directedExamined':42,'originalCutFilterApplied':True,'sharedCutFilterApplied':True}))\n"
            )
            native.chmod(0o755)
            out = root / "pair-terminal.json.gz"
            summary = extractor.resolve_original_cut_to_file(
                manifest_path=manifest, index_path=idx, buffer_path=buffer_file,
                valhalla_config_path=config, binary=native, output_path=out,
                receiver_manifest_path=b[0], receiver_index_path=b[1],
                receiver_buffer_path=b[2])
            self.assertEqual(summary["directNativeTerminalRootCount"], 1)
            self.assertEqual(summary["nonterminalSourceCutCount"], 0)
            with gzip.open(out, "rt") as stream:
                result = json.load(stream)
            self.assertEqual(result["schemaVersion"], 5)
            self.assertEqual(result["fromRegionId"], "fictional-a")
            self.assertEqual(result["toRegionId"], "fictional-b")
            self.assertEqual(result["originalPairedCutDirectedEvidence"][0]["graphId"], gid)
            self.assertEqual(result["terminalCandidatesByExactSourceGraphId"][0]
                             ["sourceCutGraphIds"], [gid])
            self.assertEqual(result["sourcePhysicalRoadDirectionCompleteness"], "NOT_VERIFIED")
            self.assertEqual(result["receiverCorrelation"], "NOT_STARTED")
            self.assertEqual(result["productionPublication"], "BLOCKED")
            with self.assertRaisesRegex(ValueError, "already exists"):
                extractor.resolve_original_cut_to_file(manifest_path=manifest,
                    index_path=idx, buffer_path=buffer_file,
                    valhalla_config_path=config, binary=native, output_path=out,
                    receiver_manifest_path=b[0], receiver_index_path=b[1],
                    receiver_buffer_path=b[2])

    def test_pair_requires_original_neighbor_and_only_shared_buffer_cut(self):
        with tempfile.TemporaryDirectory() as tmp:
            a,b = self.make_neighbor_pair(Path(tmp))
            shared = extractor.verified_shared_cut(source_manifest=a[0],
                source_index=a[1], source_buffer=a[2], receiver_manifest=b[0],
                receiver_index=b[1], receiver_buffer=b[2])
            self.assertTrue(shared["geometry"].length > 0)
            self.assertEqual(len(shared["selectedSourceTiles"]), 1)
            # The second buffered region is not actually the same territory.
            b_buffer = json.loads(b[2].read_text())
            b_buffer["geometry"] = mapping(box(10.0001, 44.0001, 10.005, 44.005))
            b[2].write_text(json.dumps(b_buffer))
            m = json.loads(b[0].read_text())
            m["source"]["bufferGeoJsonSha256"] = hashlib.sha256(b[2].read_bytes()).hexdigest()
            b[0].write_text(json.dumps(m))
            with self.assertRaisesRegex(ValueError, "no shared source cutoff"):
                extractor.verified_shared_cut(source_manifest=a[0],
                    source_index=a[1], source_buffer=a[2], receiver_manifest=b[0],
                    receiver_index=b[1], receiver_buffer=b[2])
            index = json.loads(a[1].read_text());index["boundaries"] = []
            a[1].write_text(json.dumps(index));m=json.loads(a[0].read_text())
            m["graphIndex"]["sha256"] = hashlib.sha256(a[1].read_bytes()).hexdigest()
            a[0].write_text(json.dumps(m))
            with self.assertRaisesRegex(ValueError, "reciprocal"):
                extractor.verified_shared_cut(source_manifest=a[0],
                    source_index=a[1], source_buffer=a[2], receiver_manifest=b[0],
                    receiver_index=b[1], receiver_buffer=b[2])

    def test_mode_specific_terminals_forks_and_shortcuts_remain_distinct(self):
        cut = [{"graphId":100,"endNodeGraphId":1000,"access":1025,
                "nativeTerminalModes":1,"originalCutOrientation":"OUTWARD",
                "endLat":45.,"endLon":10.}]
        def peer(gid, access, *, shortcut=False):
            return {"graphId":gid,"endNodeGraphId":gid*10,
                    "access":access,"shortcut":shortcut,
                    "transit":False,"startLat":45.,"startLon":10.,
                    "endLat":45.,"endLon":10.001}
        options = [{"viaHierarchy":False,"edge":peer(101,1024)},
                   {"viaHierarchy":True,"edge":peer(102,1024,shortcut=True)}]
        first = {"kind":"local-continuations",
                 "source":{**peer(100,1025),"endNodeGraphId":1000,"endLon":10.},
                 "options":options}
        last = {"kind":"local-continuations","source":peer(101,1024),"options":[]}
        called = []
        def read(ids):
            called.append(ids)
            return [first] if len(called)==1 else [last]
        result = extractor.select_pair_terminal_candidates(cut,read,
            source_cut_tile_ids={100,101,102},receiver_footprint=box(9,44,11,46))
        finals={x["sourceFinalCandidateGraphId"]:x for x in
                result["terminalCandidatesByExactSourceGraphId"]}
        self.assertEqual(called, [[100],[101]])
        self.assertEqual(set(finals), {100,101})
        self.assertEqual(finals[100]["terminalVehicleModes"],1)
        self.assertEqual(finals[101]["terminalVehicleModes"],1024)
        evidence=result["unresolvedNonterminalSourceCutObservations"][0]
        self.assertEqual([o["graphId"] for o in evidence["immediateNativeOutgoing"]],
                         [101,102])
        self.assertFalse(evidence["immediateNativeOutgoing"][1]["eligibleOriginalForward"])
        self.assertEqual(result["productionPublication"],"BLOCKED")

    def test_terminal_first_never_walks_outgoing_network(self):
        cut = [
            {"graphId":10,"endNodeGraphId":110,"access":1025,"nativeTerminalModes":1025,
             "originalCutOrientation":"OUTWARD","endLat":45.,"endLon":10.},
            {"graphId":11,"endNodeGraphId":111,"access":1025,"nativeTerminalModes":0,
             "originalCutOrientation":"OUTWARD","endLat":45.,"endLon":10.},
            {"graphId":12,"endNodeGraphId":112,"access":1025,"nativeTerminalModes":0,
             "originalCutOrientation":"INWARD","endLat":45.,"endLon":10.},
        ]
        def source(gid, end_lon=10.):
            return {"graphId":gid,"endNodeGraphId":100+gid,
                    "access":1025,"shortcut":False,"transit":False,
                    "startLat":45.,"startLon":10.,"endLat":45.,"endLon":end_lon}
        incoming = {"kind":"local-continuations","source":source(11),
                    "options":[{"viaHierarchy":False,"edge":source(13)},
                               {"viaHierarchy":True,"edge":source(14)}]}
        child = {"kind":"local-continuations","source":source(13),"options":[]}
        grandchild = {"kind":"local-continuations","source":source(14, 90.),
                      "options":[{"viaHierarchy":False,"edge":source(15)}]}
        calls = []
        def read(ids):
            calls.append(ids)
            return [[{"kind":"local-continuations","source":source(10),
                       "options":[]},incoming],[child, grandchild]][len(calls)-1]
        result = extractor.select_pair_terminal_candidates(cut,read,
            source_cut_tile_ids={10,11,12,13,14}, receiver_footprint=box(9,44,11,46))
        self.assertEqual(calls, [[10,11],[13,14]])
        self.assertEqual(result["outwardOrAmbiguousSourceCutCount"],2)
        self.assertEqual(result["directNativeTerminalRootCount"],1)
        self.assertEqual(result["nonterminalSourceCutCount"],1)
        self.assertEqual({x["sourceFinalCandidateGraphId"] for x in
            result["terminalCandidatesByExactSourceGraphId"]},{10,13})
        self.assertEqual(len(result["unresolvedNonterminalSourceCutObservations"]),1)
        self.assertEqual(result["sourcePhysicalRoadDirectionCompleteness"],"NOT_VERIFIED")

    def test_native_valhalla_immediate_costing_keeps_both_forks_and_unknowns(self):
        def option(gid, car, motorcycle):
            return {"viaHierarchy":False,
                    "edge":{"graphId":gid,"access":1025,"shortcut":False,
                            "transit":False,"startLat":45.,"startLon":10.,
                            "endLat":45.,"endLon":10.01},
                    "nativeImmediateCosting":{"car":car,"motorcycle":motorcycle}}
        legal = option(90,"ALLOWED_NATIVE_IMMEDIATE","ALLOWED_NATIVE_IMMEDIATE")
        unknown = option(91,"UNRESOLVED_PATH_OR_TIME_CONTEXT",
                         "UNRESOLVED_HIERARCHY_CONTEXT")
        denied = option(92,"DENIED_NATIVE_IMMEDIATE","NO_MODE_ACCESS")
        a = {"kind":"local-continuations","source":{"graphId":89},
             "options":[legal,unknown,denied]}
        extractor.validate_immediate_native_observation(a)
        self.assertEqual([o["edge"]["graphId"] for o in a["options"]],[90,91,92])
        for bad in ({"car":"ALLOWED_NATIVE_IMMEDIATE"},
                    {"car":"ACCEPTED_BY_GPS","motorcycle":"NO_MODE_ACCESS"}):
            with self.subTest(bad=bad):
                broken={**a,"options":[{**legal,"nativeImmediateCosting":bad}]}
                with self.assertRaisesRegex(ValueError,"costing"):
                    extractor.validate_immediate_native_observation(broken)

    def test_native_node_geometry_proves_distinct_branches_not_same_physical_road(self):
        def option(gid, endpoint, departure, *, car="ALLOWED_NATIVE_IMMEDIATE",
                   motorcycle="ALLOWED_NATIVE_IMMEDIATE", fromnode=500):
            return {"graphId":gid,"viaHierarchy":False,
                    "nativeVehicleModes":1025,"nativeFromNodeGraphId":fromnode,
                    "nativeEndNodeGraphId":endpoint,
                    "nativeDirectedDeparture":departure,
                    "nativeImmediateCosting":{"car":car,"motorcycle":motorcycle}}
        options=[option(10,600,[45.0001,10.0001]),
                 option(11,601,[44.9999,10.0002])]
        proof=extractor.classify_source_native_branch_topology(options,500)
        for mode in ("car","motorcycle"):
            self.assertEqual(proof[mode]["nativeTopologyStatus"],
                             "DISTINCT_NATIVE_GEOMETRIC_BRANCHES")
            self.assertEqual(proof[mode]["staticallyAllowedDirectedGraphIds"],[10,11])
            self.assertEqual(proof[mode]["physicalRoadIdentity"],"NOT_VERIFIED")
        # The same first native shape departure is NOT proof of two distinct
        # physical branches. Preserve both directed GraphIds as ambiguous.
        overlapping=[options[0],option(11,601,[45.0001,10.0001])]
        verdict=extractor.classify_source_native_branch_topology(overlapping,500)
        self.assertEqual(verdict["car"]["nativeTopologyStatus"],
                         "MULTIPLE_ALLOWED_OVERLAPPING_OR_UNKNOWN_GEOMETRY")
        # Access can differ by vehicle mode; one positive plus a possible
        # restricted branch is NOT a certified unique physical continuation.
        mode_specific=[options[0],option(11,601,[44.9999,10.0002],
                     motorcycle="UNRESOLVED_PATH_OR_TIME_CONTEXT")]
        verdict=extractor.classify_source_native_branch_topology(mode_specific,500)
        self.assertEqual(verdict["car"]["nativeTopologyStatus"],
                         "DISTINCT_NATIVE_GEOMETRIC_BRANCHES")
        self.assertEqual(verdict["motorcycle"]["nativeTopologyStatus"],
                         "SINGLE_ALLOWED_WITH_UNKNOWN_ALTERNATIVES")
        self.assertTrue(verdict["motorcycle"]["hasUnresolvedAlternatives"])
        self.assertEqual(verdict["motorcycle"]["unresolvedDirectedGraphIds"],[11])
        # Native graph ID, not near GPS, establishes the incident node.
        for bad in (option(11,601,[44.9999,10.0002],fromnode=501),
                    option(11,601,[44.9999,10.0002],fromnode=None)):
            with self.subTest(bad=bad):
                with self.assertRaisesRegex(ValueError,"exact A end node"):
                    extractor.classify_source_native_branch_topology([options[0],bad],500)
        # Native GraphId zero is permitted by Valhalla in some regional tiles;
        # never impose a geography-specific positive-index assumption.
        zero_node=[{**options[0],"nativeFromNodeGraphId":0,
                    "nativeEndNodeGraphId":0}]
        self.assertEqual(extractor.classify_source_native_branch_topology(
            zero_node,0)["car"]["nativeTopologyStatus"],
            "SINGLE_STATIC_LEGAL_CONTINUATION")
        with self.assertRaisesRegex(ValueError,"without original access"):
            extractor.classify_source_native_branch_topology([
                {**options[0],"nativeVehicleModes":1024}],500)

    def test_root_with_two_native_terminal_branches_preserves_both_and_unresolved_root(self):
        cut=[{"graphId":20,"endNodeGraphId":520,"access":1025,
              "nativeTerminalModes":0,"originalCutOrientation":"OUTWARD",
              "endLat":45.0,"endLon":10.0}]
        def source(gid, end_node, end_lon):
            return {"graphId":gid,"endNodeGraphId":end_node,
                    "access":1025,"shortcut":False,"transit":False,
                    "startLat":45.,"startLon":10.,"endLat":45.,"endLon":end_lon}
        def option(gid, end_node, departure):
            return {"viaHierarchy":False,"fromNodeGraphId":520,
                    "edge":{**source(gid,end_node,10.01),"departure":departure},
                    "nativeImmediateCosting":{
                        "car":"ALLOWED_NATIVE_IMMEDIATE",
                        "motorcycle":"ALLOWED_NATIVE_IMMEDIATE"}}
        first={"kind":"local-continuations","source":source(20,520,10.0),
               "options":[option(21,521,[45.001,10.001]),
                          option(22,522,[44.999,10.001])]}
        next_two=[{"kind":"local-continuations","source":source(gid,520+gid-20,10.01),
                   "options":[]} for gid in (21,22)]
        calls=[]
        def read(ids):
            calls.append(ids)
            return [[first],next_two][len(calls)-1]
        data=extractor.select_pair_terminal_candidates(cut,read,
            source_cut_tile_ids={20,21,22},receiver_footprint=box(9,44,11,46))
        self.assertEqual(calls,[[20],[21,22]])
        self.assertEqual({x["sourceFinalCandidateGraphId"] for x in
            data["terminalCandidatesByExactSourceGraphId"]},{21,22})
        self.assertEqual(data["nonterminalSourceCutCount"],1)
        self.assertEqual(data["singleNativeOneHopTerminalRootCount"],0)
        root=data["unresolvedNonterminalSourceCutObservations"][0]
        self.assertEqual(root["modeSpecificNativeBranchTopology"]["car"]
                         ["nativeTopologyStatus"],"DISTINCT_NATIVE_GEOMETRIC_BRANCHES")
        self.assertEqual(root["localStructuralStatus"],
                         "MULTIPLE_NATIVE_OUTGOING_UNRESOLVED")
        self.assertEqual(root["physicalRoadIdentity"],"NOT_VERIFIED")
        self.assertEqual(data["sourcePhysicalRoadDirectionCompleteness"],"NOT_VERIFIED")
        self.assertEqual(data["receiverCorrelation"],"NOT_STARTED")
        self.assertEqual(data["productionPublication"],"BLOCKED")

